import { currentUser } from "@clerk/nextjs/server";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Backed by the Clerk session. Clerk's user id is used as our stable User.id,
// and the record is upserted into the in-memory store on first sight so the
// signed-in account shows up alongside the seeded users (e.g. in the
// dashboard's team list).
export async function getCurrentUser(): Promise<User | undefined> {
  const clerkUser = await currentUser();
  if (!clerkUser) return undefined;

  const email =
    clerkUser.primaryEmailAddress?.emailAddress ??
    clerkUser.emailAddresses[0]?.emailAddress ??
    "";
  const name =
    clerkUser.fullName ?? clerkUser.username ?? email || "Unnamed user";
  const createdAt = new Date(clerkUser.createdAt).toISOString().slice(0, 10);

  return upsertUser({ id: clerkUser.id, email, name, createdAt });
}

function upsertUser(user: User): User {
  const existing = users.find((u) => u.id === user.id);
  if (existing) {
    Object.assign(existing, user);
    return existing;
  }
  users.push(user);
  return user;
}

